-- Rollback 243: remove the ten inserted BECE beta questions; preserve remediation history.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _expected_243 (question_id TEXT PRIMARY KEY, topic_id TEXT NOT NULL, subject_id TEXT NOT NULL, exam_type_id TEXT NOT NULL, question_text TEXT NOT NULL, question_type TEXT NOT NULL, options TEXT NOT NULL, correct_answer TEXT NOT NULL, explanation TEXT NOT NULL, difficulty TEXT NOT NULL, points INTEGER NOT NULL, marks INTEGER NOT NULL, time_limit INTEGER NOT NULL, command_word TEXT NOT NULL, assessment_objective TEXT NOT NULL);
DELETE FROM _expected_243;
INSERT INTO _expected_243(question_id,topic_id,subject_id,exam_type_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit,command_word,assessment_objective) VALUES
  ('q_bece_math_sets_b001_021','topic_bece_math_sets','subj_bece_math','exam_bece','If A={1,2,3,4} and B={3,4,5}, what is A \ B?','multiple_choice','["A. {3, 4}","B. {5}","C. {1, 2, 5}","D. {1, 2}"]','D','Remove the common elements 3 and 4 from A. The remaining A-only elements are 1 and 2. Therefore the correct answer is D: {1, 2}.','medium',1,1,90,'Determine','AO2'),
  ('q_bece_math_sets_b001_022','topic_bece_math_sets','subj_bece_math','exam_bece','Among 30 learners, 18 like rice, 16 like yam and 8 like both. How many like neither?','multiple_choice','["A. 4","B. 26","C. 10","D. 12"]','A','The union is 18+16−8=26. Therefore 30−26=4 learners are outside both sets. Therefore the correct answer is A: 4.','hard',1,1,90,'Calculate','AO3'),
  ('q_bece_math_sets_b001_023','topic_bece_math_sets','subj_bece_math','exam_bece','Twenty study French, fourteen study ICT and six study both. How many study only French?','multiple_choice','["A. 20","B. 14","C. 8","D. 26"]','B','The French total includes the six in the overlap, so the French-only region is 20−6=14. Therefore the correct answer is B: 14.','medium',1,1,90,'Calculate','AO2'),
  ('q_bece_math_sets_b001_024','topic_bece_math_sets','subj_bece_math','exam_bece','If n(U)=50 and n(A)=32, find n(A′).','multiple_choice','["A. 18","B. 82","C. 32","D. 2"]','A','A and its complement partition U, so n(A′)=n(U)−n(A)=50−32=18. Therefore the correct answer is A: 18.','medium',1,1,90,'Calculate','AO2'),
  ('q_bece_math_sets_b001_025','topic_bece_math_sets','subj_bece_math','exam_bece','Which set lists prime numbers below 10?','multiple_choice','["A. {1, 2, 3, 5, 7}","B. {2, 3, 5, 7}","C. {2, 4, 6, 8}","D. {3, 6, 9}"]','B','Primes greater than 1 have exactly two positive factors. Below 10 these are 2, 3, 5 and 7. Therefore the correct answer is B: {2, 3, 5, 7}.','easy',1,1,90,'Identify','AO1'),
  ('q_bece_math_sets_b001_026','topic_bece_math_sets','subj_bece_math','exam_bece','If disjoint A and B have 9 and 11 elements, find n(A∪B).','multiple_choice','["A. 2","B. 99","C. 11","D. 20"]','D','Disjoint sets have zero overlap, so the union count is 9+11−0=20. Therefore the correct answer is D: 20.','medium',1,1,90,'Calculate','AO2'),
  ('q_bece_math_sets_b001_027','topic_bece_math_sets','subj_bece_math','exam_bece','What does the region outside A but inside U represent?','multiple_choice','["A. A ∩ A","B. An empty universal set","C. A′","D. Only A’s boundary"]','C','Every point inside U but outside circle A belongs to the complement of A, denoted A′ or Aᶜ. Therefore the correct answer is C: A′.','easy',1,1,90,'Identify','AO1'),
  ('q_bece_math_sets_b001_028','topic_bece_math_sets','subj_bece_math','exam_bece','If A is multiples of 4 and B is even numbers, which is correct?','multiple_choice','["A. B ⊆ A","B. A ∩ B = ∅","C. A = ∅","D. A ⊆ B"]','D','Every multiple of 4 is divisible by 2 and therefore even, although not every even number is a multiple of 4. Therefore the correct answer is D: A ⊆ B.','hard',1,1,90,'Deduce','AO3'),
  ('q_bece_math_sets_b001_029','topic_bece_math_sets','subj_bece_math','exam_bece','A set contains the letters in LEVEL. How many distinct elements are there?','multiple_choice','["A. 3","B. 5","C. 4","D. 2"]','A','Repeated letters count once in a set. LEVEL contains the distinct letters L, E and V, giving cardinality 3. Therefore the correct answer is A: 3.','medium',1,1,90,'Calculate','AO2'),
  ('q_bece_math_sets_b001_030','topic_bece_math_sets','subj_bece_math','exam_bece','Which pair is disjoint?','multiple_choice','["A. {1,2} and {2,3}","B. {1,3,5} and {2,4,6}","C. {a,b} and {b,c}","D. {4,8} and {2,4}"]','B','Odd numbers in the first set share no member with the even numbers in the second; every other pair overlaps. Therefore the correct answer is B: {1,3,5} and {2,4,6}.','medium',1,1,90,'Compare','AO2');
CREATE TABLE IF NOT EXISTS _rollback_243_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _rollback_243_guard;
INSERT INTO _rollback_243_guard(valid) SELECT CASE WHEN
  NOT EXISTS (SELECT 1 FROM questions q JOIN _expected_243 e ON e.question_id=q.id WHERE NOT (q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective))
  AND NOT EXISTS (SELECT 1 FROM question_content_releases r JOIN _expected_243 e ON e.question_id=r.question_id WHERE NOT (r.batch_id IS 'bece-math-sets-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Common Core Programme curricula; not official WAEC or NaCCA examination material.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1))
  AND NOT EXISTS (SELECT 1 FROM question_bank_remediation_log l JOIN _expected_243 e ON e.question_id=l.entity_id WHERE l.migration_id='243_bece_math_sets_beta_part_3' AND NOT (l.migration_id IS '243_bece_math_sets_beta_part_3' AND l.entity_type IS 'question' AND l.field_name IS 'insert' AND l.old_value IS NULL AND l.new_value IS 'bece-math-sets-beta-001'))
  AND (((SELECT COUNT(*) FROM questions q JOIN _expected_243 e ON e.question_id=q.id WHERE q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective)=10 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_243 e ON e.question_id=r.question_id WHERE r.batch_id IS 'bece-math-sets-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Common Core Programme curricula; not official WAEC or NaCCA examination material.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)=10 AND (SELECT COUNT(*) FROM question_bank_remediation_log l JOIN _expected_243 e ON e.question_id=l.entity_id WHERE l.migration_id IS '243_bece_math_sets_beta_part_3' AND l.entity_type IS 'question' AND l.field_name IS 'insert' AND l.old_value IS NULL AND l.new_value IS 'bece-math-sets-beta-001')=10)
    OR ((SELECT COUNT(*) FROM questions q JOIN _expected_243 e ON e.question_id=q.id)=0 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_243 e ON e.question_id=r.question_id)=0 AND (SELECT COUNT(*) FROM question_bank_remediation_log l JOIN _expected_243 e ON e.question_id=l.entity_id WHERE l.migration_id='243_bece_math_sets_beta_part_3') IN (0,10)))
THEN 1 ELSE 0 END;
DELETE FROM questions WHERE id IN (SELECT question_id FROM _expected_243);
INSERT INTO _rollback_243_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _expected_243 e ON e.question_id=q.id)=0 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_243 e ON e.question_id=r.question_id)=0 THEN 1 ELSE 0 END;
DROP TABLE _expected_243;
DROP TABLE _rollback_243_guard;
